import subprocess

text = '''# Finally bodies need stack space for pending returns and unwind jumps.


class IDGenerator:
    def __init__(self, max_id: int):
        self._i = 0
        self._mi = max_id

    def get(self):
        try:
            return self._i
        finally:
            self._i += 1
            if self._i > self._mi:
                self._i = 0


id_gen = IDGenerator(10)
print([id_gen.get() for _ in range(13)])


def return_from_try(local):
    try:
        return 1
    finally:
        assert (local, local, local, local, local) == ("local",) * 5


print(return_from_try("local"))


def return_from_except(local):
    try:
        raise ValueError
    except ValueError:
        return 2
    finally:
        assert (local, local, local, local, local) == ("local",) * 5


print(return_from_except("local"))


def nested_return(local):
    try:
        try:
            return 3
        finally:
            assert (local, local, local, local, local) == ("local",) * 5
    finally:
        assert (local, local, local, local, local) == ("local",) * 5


print(nested_return("local"))


def break_from_try(local):
    while True:
        try:
            break
        finally:
            assert (local, local, local, local, local) == ("local",) * 5
    return local


print(break_from_try("local"))


def continue_from_try(local):
    count = 0
    while count < 2:
        count += 1
        try:
            continue
        finally:
            assert (local, local, local, local, local) == ("local",) * 5
    return local


print(continue_from_try("local"))


def break_from_finally(local):
    while True:
        try:
            break
        finally:
            break
    return local


print(break_from_finally("local"))
'''
lines = text.splitlines(True)
patch = '--- /dev/null\n+++ b/tests/basics/try_finally_stack.py\n@@ -0,0 +1,%d @@\n' % len(lines)
patch += ''.join('+' + line for line in lines)
subprocess.run(['patch', '-p1'], input=patch, text=True, check=True)
